#include <iostream>
#include <vector>

using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> a(N);
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
    }

    if (N == 1 && a[0] == 0) {
        cout << "UP\n";
        return 0;
    }
    if (N == 1 && a[0] == 15) {
        cout << "DOWN\n";
        return 0;
    }
    if (N == 1 && a[0] != 0 && a[0] != 15) {
        cout << -1 << '\n';
        return 0;
    }

    if (a[N - 2] > a[N - 1] && a[N - 1] != 0) {
        cout << "DOWN\n";
        return 0;
    }
    if (a[N - 2] < a[N - 1] && a[N - 1] != 15) {
        cout << "UP\n";
        return 0;
    }
    if (a[N - 1] == 0) {
        cout << "UP\n";
        return 0;
    }
    if (a[N - 1] == 15) {
        cout << "DOWN\n";
        return 0;
    }

    return 0;
}

